/* Generated by tools/build-data.js from the source Markdown. Do not edit by hand. */
window.LAB_DATA = window.LAB_DATA || {};
window.LAB_DATA.hr = [{"id":"HR-001","n":1,"section":"hr","category":"About You","tag":"Introduction","title":"Tell me about yourself.","keywords":["tell","me","about","yourself","introduction"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"Good morning sir/ma'am. My name is Sandeep. I am currently pursuing my\ndiploma and preparing myself for a software development role. I have\nbeen strengthening programming, DSA, web development and core CS\nfundamentals such as OOPs, DBMS, Operating Systems and Computer\nNetworks.\n\nI like learning by building projects and solving practical problems. My\ngoal is to start my career as a software developer, contribute to real\nprojects and keep improving my technical and communication skills."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: What are you learning now?** A: I am strengthening DSA, core CS and\ndevelopment skills while practicing interview questions and projects."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Keep it around 60--90 seconds; do not tell your complete life story."}]},{"id":"HR-002","n":2,"section":"hr","category":"About You","tag":"Company","title":"Why do you want to join Allied Softech?","keywords":["why","want","join","allied","softech","company","about"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I want to start my software development career in an environment where I\ncan work on real software projects and learn professional development\npractices. The role matches the areas I am preparing for, including\nprogramming, databases, web technologies and problem solving.\n\nAs a fresher, I want to learn from experienced people, take\nresponsibility and gradually contribute more to the team."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Why our company?** A: The role, learning opportunity and chance to\nwork on real software are the main reasons."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not make salary your main reason or invent company facts."}]},{"id":"HR-003","n":3,"section":"hr","category":"About You","tag":"Company","title":"What do you know about our company?","keywords":["know","about","our","company"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"From my research, I understand that Allied Softech is a software-focused\ncompany working on business and technology solutions. I have also\nreviewed the developer role requirements so I can prepare around\nrelevant programming and software fundamentals.\n\nI would also like to understand more about the specific product and team\nI would join."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Did you research us?** A: Yes. I reviewed company information and\nrole requirements and focused my preparation on relevant technical\nareas."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Never invent clients, products or technologies."}]},{"id":"HR-004","n":4,"section":"hr","category":"About You","tag":"Motivation","title":"Why software development?","keywords":["why","software","development","motivation","about"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I like software development because it combines logic, problem solving\nand creativity. I enjoy breaking a problem into smaller parts and\nbuilding a working solution.\n\nI also like continuous improvement. A solution can be made clearer,\nfaster, safer or easier to maintain, so there is always something new to\nlearn."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: What if development becomes difficult?** A: I break the problem\ndown, reproduce the issue, research the relevant concept and test a\nsolution step by step."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not answer only 'I like coding.'"}]},{"id":"HR-005","n":5,"section":"hr","category":"Self-Assessment","tag":"Strength","title":"What are your strengths?","keywords":["your","strengths","strength","self","assessment"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"My main strengths are consistency, willingness to learn and a\nproblem-solving mindset. When I do not understand something, I break it\ninto smaller parts and practice it rather than only memorizing an\nanswer.\n\nI also try to use feedback to improve my work."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Give an example.** A: I regularly revise technical topics through\ncoding practice and projects so I can convert theory into practical\nunderstanding."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Choose 2--3 strengths and support them with behaviour."}]},{"id":"HR-006","n":6,"section":"hr","category":"Self-Assessment","tag":"Weakness","title":"What is your weakness?","keywords":["your","weakness","self","assessment"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"One area I am improving is spending too much time trying to make a\nsolution perfect. I am learning to first build a correct solution, test\nit and then improve it based on priority and deadline.\n\nThis helps me balance quality with time management."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Is it still a problem?** A: Sometimes, but I am more conscious of\ntime now and use priorities to decide when additional improvement is\nnecessary."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not give a fake weakness like 'I work too hard.'"}]},{"id":"HR-007","n":7,"section":"hr","category":"Self-Assessment","tag":"Learning","title":"What do you do when you do not know an answer?","keywords":["when","not","know","answer","learning","self","assessment"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I prefer to be honest rather than guess. I would explain what I know,\nthink through the problem and ask for clarification if needed.\nAfterward, I would learn the missing concept properly.\n\nI believe a strong learning attitude is better than giving a confident\nbut incorrect answer."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: How do you learn a new technology?** A: I start with fundamentals\nand documentation, build a small example and then apply it to a\npractical task."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Never bluff technical knowledge."}]},{"id":"HR-008","n":8,"section":"hr","category":"Work Approach","tag":"Problem Solving","title":"How do you approach a difficult technical problem?","keywords":["approach","difficult","technical","problem","solving","work"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"First I understand the requirement, input and expected output. Then I\ncreate a small example and think of a simple correct approach.\n\nAfter that I analyze complexity and look for optimization if required.\nIf I am stuck, I isolate the exact issue and research or ask a focused\nquestion."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: What if your first solution fails?** A: I identify the failing\ncase, understand why, fix the logic and test edge cases."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not say you immediately search for the final solution."}]},{"id":"HR-009","n":9,"section":"hr","category":"Work Approach","tag":"Debugging","title":"How do you debug a bug?","keywords":["debug","bug","debugging","work","approach"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"First I reproduce the issue. Then I compare expected and actual\nbehaviour and isolate the smallest area that can be responsible.\n\nI inspect inputs, outputs, logs or debugger information, form a\nhypothesis, test it and verify the fix with normal and edge cases."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Do you randomly change code?** A: No. I prefer hypothesis-driven\ndebugging so I know why the issue was fixed."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not make 'Google it' your complete debugging process."}]},{"id":"HR-010","n":10,"section":"hr","category":"Teamwork & Pressure","tag":"Teamwork","title":"How do you work in a team?","keywords":["work","team","teamwork","pressure"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I believe good teamwork needs clear communication, ownership and\nrespect. I understand my responsibility and deadlines, communicate\ndependencies early and keep teammates updated when something affects the\nplan.\n\nI also believe disagreements should be based on requirements and facts\nrather than personal opinions."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Difficult teammate?** A: I would speak directly first, understand\nthe reason and try to solve it. I would escalate professionally only if\nit affects the project and cannot be resolved."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not blame teammates."}]},{"id":"HR-011","n":11,"section":"hr","category":"Teamwork & Pressure","tag":"Conflict","title":"What if you disagree with your senior?","keywords":["if","disagree","your","senior","conflict","teamwork","pressure"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I would first understand the senior's reasoning. If I still have a\ndifferent technical opinion, I would explain it respectfully using\nfacts, examples and trade-offs.\n\nIf the final decision is different, I would support it professionally\nunless there is a serious technical, security or ethical concern."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: What if you are sure you are right?** A: I would present evidence\nand let the responsible person make the final project decision."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not sound ego-driven."}]},{"id":"HR-012","n":12,"section":"hr","category":"Teamwork & Pressure","tag":"Pressure","title":"How do you handle pressure?","keywords":["handle","pressure","teamwork"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I separate urgent work from important work, break tasks into smaller\npieces and focus on the highest-priority work first. If a deadline\nbecomes risky, I communicate early instead of hiding the problem.\n\nI also keep testing time because rushing without verification can create\nbigger problems."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Impossible deadline?** A: I would explain the remaining work and\ndiscuss priority, scope or timeline trade-offs."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not say 'I never feel pressure.'"}]},{"id":"HR-013","n":13,"section":"hr","category":"Self-Assessment","tag":"Failure","title":"Tell me about a failure.","keywords":["tell","me","about","failure","self","assessment"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"Earlier, I sometimes underestimated the time required for technical\ntasks because I focused mainly on implementation. I learned that testing\nand unexpected issues also need time.\n\nNow I break work into smaller parts, identify risky areas early and keep\ntime for testing."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: What did you learn?** A: Better estimation, testing and early\ncommunication."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Use a real, safe example and show changed behaviour."}]},{"id":"HR-014","n":14,"section":"hr","category":"Self-Assessment","tag":"Feedback","title":"How do you handle criticism?","keywords":["handle","criticism","feedback","self","assessment"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I try to separate feedback from my ego. I first understand the reason\nand ask questions if something is unclear.\n\nIf the feedback is valid, I apply it and try to prevent the same mistake\nin future. Constructive feedback can help me improve faster."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: What if you disagree?** A: I would ask for examples and discuss the\nissue respectfully using project requirements and facts."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not say you dislike criticism."}]},{"id":"HR-015","n":15,"section":"hr","category":"Projects","tag":"Project","title":"Explain your project.","keywords":["explain","your","project","projects"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I would explain my project in this order: the problem it solves, main\nfeatures, technologies used, my individual contribution, one technical\nchallenge and how I solved it. Finally, I would mention what I would\nimprove with more time.\n\nThis structure keeps the explanation clear and gives the interviewer\nopportunities to ask technical questions."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Biggest challenge?** A: I would explain one real issue, how I\nreproduced it, what I tried and how I verified the solution."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Know every technology and feature on your resume."}]},{"id":"HR-016","n":16,"section":"hr","category":"Projects","tag":"Project","title":"What was your contribution?","keywords":["was","your","contribution","project","projects"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I would clearly separate my own work from the team's work. I would\nmention the exact features or modules I implemented and explain the\ndecisions I made.\n\nI would never claim ownership of work done by someone else."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: What did you learn?** A: I would mention the specific technical and\nteamwork skills gained from my contribution."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not say 'I made everything' in a team project."}]},{"id":"HR-017","n":17,"section":"hr","category":"Work Approach","tag":"Technology","title":"Why did you choose your technology?","keywords":["why","did","choose","your","technology","work","approach"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I choose technology based on project requirements, team familiarity,\necosystem support, maintainability and development speed.\n\nFor example, JavaScript is useful for browser interaction and has a\nlarge ecosystem. The final choice should still depend on actual project\nrequirements."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Would you change it now?** A: If requirements changed, I would\nreassess the trade-offs rather than changing technology only because\nanother option is popular."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not say 'because everyone uses it.'"}]},{"id":"HR-018","n":18,"section":"hr","category":"Offer & Logistics","tag":"Salary","title":"What are your salary expectations?","keywords":["your","salary","expectations","offer","logistics"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"As a fresher, my first priority is a good learning opportunity and\nstarting my software development career. I am comfortable discussing\ncompensation according to the company's standard range for the role and\nresponsibilities."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Specific number?** A: I am open to a fair offer based on the role\nand company range, and I am flexible at this stage."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not sound desperate or give an unsupported unrealistic number."}]},{"id":"HR-019","n":19,"section":"hr","category":"Offer & Logistics","tag":"Relocation","title":"Are you comfortable relocating?","keywords":["comfortable","relocating","relocation","offer","logistics"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"Yes, I am open to relocation if the role requires it. My priority is a\ngood professional opportunity where I can learn, contribute and grow. I\nwould just like to understand the location and working arrangement\nclearly."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Any constraints?** A: I would be honest about genuine constraints,\nbut I am generally open to relocation for the right opportunity."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Be truthful about actual constraints."}]},{"id":"HR-020","n":20,"section":"hr","category":"Offer & Logistics","tag":"Work Style","title":"Are you comfortable working from office?","keywords":["comfortable","working","from","office","work","style","offer","logistics"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"Yes. I am comfortable working from the office. As a fresher, I also see\nvalue in being around experienced developers because collaboration,\nfeedback and learning can become easier."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Hybrid?** A: I am comfortable adapting to the team's working model."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not criticize office work."}]},{"id":"HR-021","n":21,"section":"hr","category":"Career & Closing","tag":"Career","title":"Where do you see yourself in 3--5 years?","keywords":["where","see","yourself","years","career","closing"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I want to become a strong software developer who can independently own\nfeatures, understand technical trade-offs and contribute reliably to a\ndevelopment team.\n\nI also want to keep improving DSA, core CS, development and\ncommunication skills and gradually take more responsibility."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Management?** A: My immediate focus is technical strength. Later, I\nwould be open to leadership responsibilities if they fit my skills and\ninterests."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Keep goals realistic for a fresher."}]},{"id":"HR-022","n":22,"section":"hr","category":"Teamwork & Pressure","tag":"Requirements","title":"What if requirements change after you start coding?","keywords":["if","requirements","change","after","start","coding","teamwork","pressure"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I would first confirm what changed and why. Then I would assess the\nimpact on existing work, dependencies and deadline. I would update the\nplan and communicate risks before implementing the change."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: What about work already done?** A: I would reuse anything still\nuseful and adapt the rest to the new requirement."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not complain about changing requirements."}]},{"id":"HR-023","n":23,"section":"hr","category":"Teamwork & Pressure","tag":"Ethics","title":"What if you find a serious bug just before release?","keywords":["if","find","serious","bug","just","before","release","ethics","teamwork","pressure"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I would communicate the issue immediately with its impact, reproduction\nsteps and current status. I would not hide it just to meet a deadline.\n\nThen I would work with the team to decide whether to fix, roll back,\ndelay or use a safe mitigation."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Manager says hide it?** A: I would explain the risk and follow the\ncompany's escalation and compliance process for serious issues."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Never say you would silently ship a serious known issue."}]},{"id":"HR-024","n":24,"section":"hr","category":"Work Approach","tag":"Quality","title":"How do you ensure code quality?","keywords":["ensure","code","quality","work","approach"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I first understand the requirement, implement a clear solution, test\nnormal and edge cases, review the code and verify the final behaviour\nagainst the requirement. Where available, I value peer review and\nautomated tests."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Does testing guarantee no bugs?** A: No. Testing reduces risk but\ncannot prove every possible issue is impossible."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not claim code is always bug-free."}]},{"id":"HR-025","n":25,"section":"hr","category":"Work Approach","tag":"Communication","title":"Explain a technical concept to a non-technical person.","keywords":["explain","technical","concept","non","person","communication","work","approach"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"I avoid unnecessary technical terms and first understand what the person\nneeds to know. For example, I can explain a database as an organized\ndigital filing system where information can be stored, searched and\nupdated efficiently. If more detail is needed, I gradually introduce\ntechnical terms."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Q: Why communication matters?** A: Developers work with teammates,\nproduct people and users, so requirements and limitations must be\nunderstood clearly."},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not use jargon just to sound technical."}]},{"id":"HR-026","n":26,"section":"hr","category":"Career & Closing","tag":"Closing","title":"Do you have any questions for us?","keywords":["have","any","questions","us","closing","career"],"sections":[{"title":"Interview Answer","kind":"core","orig":"Interview Answer --- Simple English","body":"Yes, thank you. I would like to know what the first few months for a\nfresher in this role usually look like, what kind of projects or\ntechnologies the selected candidate may initially work with, and what\nyou would consider a successful first six months."},{"title":"Possible Follow-up + Answer","kind":"followups","orig":"Possible Follow-up + Answer","body":"**Alternative:** What skills would you recommend I strengthen before\njoining so I can contribute more effectively?"},{"title":"Common Mistakes","kind":"mistakes","orig":"Common Mistake / Avoid","body":"Do not ask only about salary, leave or holidays in the first closing\nconversation."}]}];
